class_name DialogPlayer

@export var tree: DialogTree

signal line_shown(speaker: String, text: String, choices_labels: Array)
signal dialog_finished

var current_node: DialogNode = null
var _flags: Dictionary = {}

func start():
	if not tree:
		push_error("No dialog tree assigned.")
		return
	current_node = tree.get_node(tree.start_id)
	if current_node:
		_emit_line()

func advance(choice_index: int = -1):
	if not current_node:
		return

	var next_id: StringName = ""
	if current_node.choices.size() > 0:
		# Only count choices that are visible
		var visible_choices = []
		for choice in current_node.choices:
			if choice.condition_flag.is_empty() or has_flag(choice.condition_flag):
				visible_choices.append(choice)

		if choice_index >= 0 and choice_index < visible_choices.size():
			next_id = visible_choices[choice_index].next_id
		else:
			# No valid choice picked, don't advance or treat as end?
			# Requirement implies advance via next_id if no choices - let's treat invalid choice as end for safety or do nothing
			# Let's emit finished
			dialog_finished.emit()
			current_node = null
			return
	else:
		next_id = current_node.next_id

	if next_id.is_empty():
		dialog_finished.emit()
		current_node = null
		return

	current_node = tree.get_node(next_id)
	if current_node:
		_emit_line()
	else:
		dialog_finished.emit()

func set_flag(name: StringName):
	_flags[name] = true

func has_flag(name: StringName) -> bool:
	return _flags.has(name)

func _emit_line():
	var choices_labels = []
	for choice in current_node.choices:
		if choice.condition_flag.is_empty() or has_flag(choice.condition_flag):
			choices_labels.append(choice.label)

	line_shown.emit(current_node.speaker, current_node.text, choices_labels)

