extends SceneTree

func _init():
	var root = Control.new()
	root.name = "DialogUI"
	root.set_anchors_preset(Control.PRESET_FULL_RECT)

	var vbox = VBoxContainer.new()
	vbox.name = "Layout"
	vbox.set_anchors_preset(Control.PRESET_FULL_RECT)
	vbox.set_anchor_and_offset(SIDE_BOTTOM, 1.0, 0)
	root.add_child(vbox)
	vbox.set_owner(root)

	var speaker = Label.new()
	speaker.name = "Speaker"
	vbox.add_child(speaker)
	speaker.set_owner(root)

	var text = RichTextLabel.new()
	text.name = "Text"
	text.fit_content = true
	vbox.add_child(text)
	text.set_owner(root)

	var choices = VBoxContainer.new()
	choices.name = "Choices"
	vbox.add_child(choices)
	choices.set_owner(root)

	var scene = PackedScene.new()
	var result = scene.pack(root)
	if result == OK:
		ResourceSaver.save(scene, "res://scenes/DialogUI.tscn")
		print("Done")

	quit()

extends Control

@export var player: DialogPlayer
@onready var speaker = $Layout/Speaker
@onready var text = $Layout/Text
@onready var choices = $Layout/Choices

func _ready():
	if player:
		player.line_shown.connect(_on_line_shown)
		player.dialog_finished.connect(_on_finished)
		player.start()

func _on_line_shown(speaker_name: String, body_text: String, choices_labels: Array):
	speaker.text = speaker_name
	text.text = body_text

	for child in choices.get_children():
		child.queue_free()

	for i in choices_labels.size():
		var btn = Button.new()
		btn.text = choices_labels[i]
		btn.pressed.connect(_on_choice_pressed.bind(i))
		choices.add_child(btn)

func _on_choice_pressed(index: int):
	player.advance(index)

func _on_finished():
	speaker.text = ""
	text.text = "[Dialog Finished]"

