func _init():
	var DialogPlayer_script = load("res://scripts/DialogPlayer.gd")
	var scene = load("res://scenes/DialogUI.tscn").instantiate()
	scene.script = load("res://scripts/DialogUI.gd")

	var player = DialogPlayer_script.new()
	player.name = "DialogPlayer"
	player.tree = load("res://resources/dialogs/intro.tres")
	scene.add_child(player)
	player.set_owner(scene)

	scene.player = player

	var packed = PackedScene.new()
	packed.pack(scene)
	ResourceSaver.save(packed, "res://scenes/DialogUI.tscn")
	print("Done")
	quit()

